"""Author-written additions. Public teaching material, never grading mappings.

The reader can start without a business, paid accounts or a human grader.
The actual assessment identities are read privately by the assembler.
"""

CARDS = {}


def card(lesson, opening, skills, terms, explanation, task, checks, sample, retry,
         action, alternatives):
    assert lesson not in CARDS
    assert len(skills) == len(checks) == 3 and len(alternatives) == 2
    CARDS[lesson] = dict(opening=opening, skills=skills, terms=terms,
        explanation=explanation, task=task, checks=checks, sample=sample,
        retry=retry, action=action, alternatives=alternatives)


